llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Aprepitant, a close high-transfer analogue with a fluorophenyl and heterocyclic CNS scaffold, has absolute oral bioavailability 0.59–0.65 in fasted humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Silodosin, another high-transfer analogue, has absolute oral bioavailability 32.2% in healthy men, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Bepotastine, containing a piperidine and chlorophenyl motif, shows >80% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Encainide, despite first-pass variability, has mean oral bioavailability 30 ± 7% in normal subjects, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Lemborexant has at least 87% oral bioavailability in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride has absolute oral bioavailability of 72.5%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Basmisanil has absolute bioavailability of approximately 75% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Haloperidol, a piperidine-containing antipsychotic, has absolute oral bioavailability of 60–70%, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from close structural analogues reports absolute oral bioavailability above 20%, mostly 30–87%, and the query's CNS-type scaffold with a piperidine and fluorinated heteroaromatic is consistent with these high-bioavailability drugs. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is included; prediction relies on high-transfer analogues.",
    "Encainide shows wide interindividual bioavailability (range 7–82%), but its mean is above threshold and does not support a low prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

